/**
 * Font bytes for the social card, vendored as base64.
 *
 * Deliberately NOT read from node_modules with fs at runtime — see the note in
 * og-fonts.ts. A module-scope readFileSync resolved against process.cwd() threw
 * on the host and took down every on-demand metadata render with it. Inlining
 * removes the filesystem, the working directory and node_modules from the
 * runtime path entirely.
 *
 * Source: @fontsource latin subsets, .woff — Satori parses ttf/otf/woff but NOT
 * woff2, which is why the copies next/font emits into .next cannot be reused.
 *
 * Generated. Regenerate by base64-ing the .woff files if the card changes weight.
 */

const SPACE_GROTESK_700_B64 = "";
export const spaceGrotesk700 = Buffer.from(SPACE_GROTESK_700_B64, "base64");

const URBANIST_500_B64 = "";
export const urbanist500 = Buffer.from(URBANIST_500_B64, "base64");

const URBANIST_600_B64 = "";
export const urbanist600 = Buffer.from(URBANIST_600_B64, "base64");

const JETBRAINS_MONO_600_B64 = "";
export const jetbrainsMono600 = Buffer.from(JETBRAINS_MONO_600_B64, "base64");
